declare(strict_types=1);

namespace Toolkit\PhpStan\Rule\Type;

use PHPStan\Node\ClassPropertyNode;
use PHPStan\Rules\IdentifierRuleError;

use function sprintf;

/**
 * Collects mixed diagnostics from stored property contracts.
 *
 * @visibility namespace
 */
final class MixedPropertyErrorCollector
{
    /** @readonly */
    private ConcreteMixedTypeInspector $typeInspector;

    /** @readonly */
    private MixedVisibilityDetector $visibilityDetector;

    /** @readonly */
    private MixedTypeErrorBuilder $errorBuilder;

    /**
     * Creates the collector from type and visibility policies.
     */
    public function __construct(
        ?ConcreteMixedTypeInspector $typeInspector = null,
        ?MixedVisibilityDetector $visibilityDetector = null,
        ?MixedTypeErrorBuilder $errorBuilder = null,
    ) {
        $this->typeInspector = $typeInspector ?? new ConcreteMixedTypeInspector();
        $this->visibilityDetector = $visibilityDetector ?? new MixedVisibilityDetector();
        $this->errorBuilder = $errorBuilder ?? new MixedTypeErrorBuilder();
    }

    /**
     * Collects an error from one internal property declaration.
     *
     * @return list<IdentifierRuleError>
     */
    public function errors(ClassPropertyNode $node): array
    {
        $class = $node->getClassReflection();
        $restricted = $node->isPrivate()
            || $this->visibilityDetector->classIsRestricted($class)
            || $this->visibilityDetector->isRestricted(
                $node->getPhpDoc(),
                $class->getNativeReflection()->getNamespaceName()
            );
        if (!$restricted) {
            return [];
        }

        $type = $node->getPhpDocType() ?? $node->getNativeType();
        if ($type === null || !$this->typeInspector->contains($type)) {
            return [];
        }

        return [$this->errorBuilder->build(
            $this->typeInspector->describe($type),
            'property type',
            sprintf('%s::$%s', $class->getDisplayName(), $node->getName()),
            $node->getOriginalNode()->getStartLine()
        )];
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\PhpStan\Rule\Type;

use PHPStan\Type\Generic\TemplateType;
use PHPStan\Type\MixedType;
use PHPStan\Type\Type;
use PHPStan\Type\TypeTraverser;
use PHPStan\Type\VerbosityLevel;

/**
 * Finds explicit, non-template mixed inside a resolved PHPStan type.
 *
 * @visibility namespace
 */
final class ConcreteMixedTypeInspector
{
    /**
     * Reports whether a resolved declaration contains concrete mixed.
     */
    public function contains(Type $type): bool
    {
        $contains = false;
        TypeTraverser::map(
            $type,
            static function (Type $inner, callable $traverse) use (&$contains): Type {
                if ($inner instanceof TemplateType) {
                    return $inner;
                }

                if ($inner instanceof MixedType && $inner->isExplicitMixed()) {
                    $contains = true;
                }

                return $traverse($inner);
            }
        );

        return $contains;
    }

    /**
     * Describes the complete declaration that contains mixed.
     */
    public function describe(Type $type): string
    {
        return $type->describe(VerbosityLevel::typeOnly());
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\PhpStan\Rule\Type\Rule;

use PHPStan\Analyser\Scope;
use PHPStan\Node\ClassPropertyNode;
use PHPStan\Rules\IdentifierRuleError;
use PHPStan\Rules\Rule;
use Toolkit\PhpStan\Rule\Type\MixedPropertyErrorCollector;

/**
 * Applies the internal mixed policy to stored properties.
 *
 * @implements Rule<ClassPropertyNode>
 */
final class ForbidInternalMixedPropertyRule implements Rule
{
    /** @readonly */
    private MixedPropertyErrorCollector $collector;

    /**
     * Creates the rule from property declaration inspection.
     */
    public function __construct(?MixedPropertyErrorCollector $collector = null)
    {
        $this->collector = $collector ?? new MixedPropertyErrorCollector();
    }

    /**
     * @return class-string<ClassPropertyNode>
     */
    public function getNodeType(): string
    {
        return ClassPropertyNode::class;
    }

    /**
     * @param ClassPropertyNode $node
     * @return list<IdentifierRuleError>
     */
    public function processNode(\PhpParser\Node $node, Scope $scope): array
    {
        unset($scope);

        return $this->collector->errors($node);
    }
}

